prompt:
Create unit `tasks` and implement `max_index`: for a non-empty array, an index of a largest element. The contract must state that the index is in bounds and no element is larger than the one at that index.

Required signature (in unit `tasks`):
fn max_index(a: &[i64]) -> (r: usize)

reference.code:
spec fn nonempty(a: &[i64]) -> bool { a.len() > 0 }

spec fn best_below(a: &[i64], n: usize, b: usize) -> bool { b < a.len() && (forall|k: usize| k < n ==> #[trigger] a[k] <= a[b]) }

spec fn is_max_index(a: &[i64], r: usize) -> bool { r < a.len() && (forall|k: usize| k < a.len() ==> #[trigger] a[k] <= a[r]) }

#[effects(pure)]
#[uses(nonempty, best_below, is_max_index)]
fn max_index(a: &[i64]) -> (r: usize)
    requires nonempty(a),
    ensures is_max_index(a, r),
{
    let mut b: usize = 0;
    let mut k: usize = 1;
    while k < a.len()
        invariant 1 <= k, k <= a.len(), best_below(a, k, b),
        decreases a.len() - k,
    {
        if a[k] > a[b] {
            b = k;
        }
        k = k + 1;
    }
    b
}
